import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.util.Comparator;
import java.util.Collections;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskF solver = new TaskF();
        solver.solve(1, in, out);
        out.close();
    }
    static class TaskF {
        private int N;
        private int MOD = 1_000_000_007;
        private int[][] dp1;
        private int[][] dp2;
        private boolean[][] visited;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            N = in.nextInt();
            dp1 = new int[N+1][N+1];
            dp2 = new int[N+1][N+1];
            visited = new boolean[N+1][N+1];
            // compute using recursion with memoization
            int[] result = compute(0, 0);
            int ans = Math.max(result[0], result[1]);
            out.print("" + ans);
            out.println();
        }

        private int[] compute(int x, int y) {
            if (visited[x][y]) {
                return new int[]{dp1[x][y], dp2[x][y]};
            }
            int d1 = 0, d2 = 0;
            // calc d2
            if (x+1 <= N) {
                int[] next = compute(x+1, y);
                int m = Math.max(next[0], next[1]);
                d2 += m;
            }
            d2 %= MOD;
            if (y+1 <= Math.min(x, N)) {
                int[] next = compute(x, y+1);
                int m = Math.max(next[0], next[1]);
                d2 += m;
            }
            d2 %= MOD;

            if (x+1 <= N) {
                int[] next = compute(x+1, y);
                int m = Math.max(next[0], next[1]);
                d1 = Math.max(d1, 1 + d2 - m + next[1]);
                d1 %= MOD;
                if (d1 < 0) d1 += MOD;
            }
            if (y+1 <= Math.min(x, N)) {
                int[] next = compute(x, y+1);
                int m = Math.max(next[0], next[1]);
                d1 = Math.max(d1, 1 + d2 - m + next[1]);
                d1 %= MOD;
                if (d1 < 0) d1 += MOD;
            }
            d1 %= MOD;
            if (d1 < 0) d1 += MOD;
            d2 %= MOD;
            if (d2 < 0) d2 += MOD;

            dp1[x][y] = d1;
            dp2[x][y] = d2;
            visited[x][y] = true;
            return new int[]{d1, d2};
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
